Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
Import-Module (Join-Path $PSScriptRoot '../ResearchAutomation.ResearchIntake.psd1') -Force
function Get-RapIntakeThrown([scriptblock]$Action){try{&$Action|Out-Null;''}catch{$_.Exception.Message}}
function New-RapIntakeFixture([string]$CandidateId='C-001',[string]$Doi='10.1234/RAP.001',[string]$Title='Research Intake Safety',[string]$Author='Kim',[string]$Year='2026',[string]$Pmid=''){[pscustomobject]@{CandidateId=$CandidateId;Doi=$Doi;Title=$Title;FirstAuthor=$Author;Year=$Year;Pmid=$Pmid;Pmcid='';PublisherId='';Source='mock-index';Provenance='fixture:approved'}}
function New-RapIntakeContext([object[]]$Canonical=@(),[object[]]$Zotero=@(),[object[]]$Results=@((New-RapIntakeFixture))){$store=New-RapResearchIntakeStore -KnownProjectIds PR015 -ExistingCanonicalPapers $Canonical -ExistingZoteroItems $Zotero;$null=New-RapResearchQuestion $store PR015 RQ-015 'How can research intake prevent duplicates?' 'researcher:turn-a';$request=New-RapSearchRequest $store PR015 RQ-015 QUICK 'zero duplicate research intake' @{} 'researcher:turn-a' SE-015;$search=@(Invoke-RapMockResearchSearch $store $request $Results);$inbox=@(Add-RapResearchInboxCandidates $store $search 'MOCK_SEARCH_RESULT');[pscustomobject]@{Store=$store;Request=$request;Search=$search;Inbox=$inbox}}
function Promote-RapFixture($Context,[string]$CandidateId='C-001'){Promote-RapResearchInboxCandidate $Context.Store PR015 RQ-015 $CandidateId 'turn-a-researcher' 'explicit-promote:turn-a'}
